const { itemType } = options;
const item = window.getItem();
const currentState = aras.getItemProperty(item, 'h4_directaplist');

const resultOptions = { disabled: false };

if (currentState !== "Approved" && currentState !== "ProvisionalApproved") {
    Object.assign(resultOptions, { disabled: true });
}

return resultOptions;
